-- Source-only candidate; production unchanged. Player-specific Deck/Grave permissions unproven.
function s.gydestination(c) if c:GetDestination()~=LOCATION_GRAVE or c:GetLeaveFieldDest()~=0 then return false end for _,re in ipairs({c:IsHasEffect(EFFECT_TO_GRAVE_REDIRECT)}) do local v=re:GetValue() if type(v)=="function" then v=v(re,c,c:GetReason()) end if bit.band(v,LOCATION_HAND)~=0 and c:IsAbleToHand(re:GetHandlerPlayer()) then return false end if bit.band(v,LOCATION_DECK)~=0 and c:IsAbleToDeck() then return false end if bit.band(v,LOCATION_REMOVED)~=0 and not c:IsHasEffect(EFFECT_CANNOT_REMOVE) and Duel.IsPlayerCanRemove(re:GetHandlerPlayer(),c,REASON_EFFECT) then return false end if bit.band(v,LOCATION_GRAVE)~=0 and c:IsAbleToGrave(REASON_EFFECT) then return true end end return true end
